with valid as (select *, length(account_type) as account_type_length, coalesce(status, 'NONE') as status_clean from accounts where customer_id is not null and balance > 19000), ranked as (select id, account_type, opened_date, account_type_length from (select *, row_number() over (partition by status, customer_id order by opened_date asc, id asc) as dedup_rank from valid) x where dedup_rank = 1), scored as (select *, avg(account_type_length) over (partition by account_type order by opened_date asc, id asc rows between 3 preceding and current row) as last4_avg_account_type_length, max(account_type_length) over (partition by account_type order by opened_date asc, id asc rows between 3 preceding and current row) as last4_max_account_type_length, sum(account_type_length) over (partition by account_type order by opened_date asc, id asc rows between 3 preceding and current row) as last4_sum_account_type_length, count(account_type_length) over (partition by account_type order by opened_date asc, id asc rows between 3 preceding and current row) as last4_count_account_type_length from ranked where opened_date <= '2024-06-01'), deduped as (select * from (select *, row_number() over (partition by account_type order by last4_avg_account_type_length asc nulls last, id asc) as rn from scored) t where rn = 1) select case when last4_sum_account_type_length >= 420 then 'PREMIUM' else 'STANDARD' end as last4_sum_account_type_length_tier, sort_array(collect_set(account_type)) as account_type_list, size(collect_set(account_type)) as num_account_types, count_if(account_type = 'SAVINGS') as savings_events from deduped group by case when last4_sum_account_type_length >= 420 then 'PREMIUM' else 'STANDARD' end;
